# Pièces supplémentaires des dossiers d'enquête de l'atlas du collège, volet « Conquêtes et sociétés coloniales » :
# une par enquête + sa question (parcours guidé qp, parcours autonome qc). Fiches de l'atlas, sans personnage inventé.
def Q(q, a): return {'k': 'qcm', 'q': q, 'a': a}
def V(q, ok): return {'k': 'vf', 'q': q, 'a': ok}
def W(q, m): return {'k': 'libre', 'q': q, 'm': m}

X = {
'colonies-1': dict(kind='fiche', t='Fiche : colonie ou protectorat ?', src='Fiche de l’atlas.',
 txt="Dans une colonie, la France gouverne directement : un gouverneur nommé par Paris dirige le territoire. C'est le cas de la Nouvelle-Calédonie ou de la Cochinchine.\nDans un protectorat, le souverain reste en place : le bey à Tunis, le sultan au Maroc, l'empereur en Annam. Mais un résident français décide de l'essentiel : l'armée, les impôts, les relations avec les autres pays.\nDans les deux cas, les habitants ne choisissent pas ceux qui les gouvernent.",
 qp=Q('Dans un protectorat, qui décide de l’essentiel ?', ['Le résident français', 'Le souverain local, seul', 'Les habitants, par un vote']),
 qc=W('Explique la différence entre une colonie et un protectorat, avec un exemple de chaque.', 'Dans une colonie (Nouvelle-Calédonie, Cochinchine), la France gouverne directement par un gouverneur. Dans un protectorat (Tunisie, Maroc, Annam), le souverain reste en place, mais un résident français décide de l’essentiel. Dans les deux cas, les habitants ne décident pas.')),
'colonies-2': dict(kind='fiche', t='Fiche : des frontières tracées à la règle', src='Fiche de l’atlas.',
 txt="Regarde la frontière entre l'Égypte et la Libye, ou entre l'Algérie et le Mali : de longues lignes droites.\nElles ont été tracées en Europe, sur des cartes, par des diplomates qui ne connaissaient pas le terrain. Ils ont souvent suivi un méridien ou un parallèle.\nRésultat : des peuples se retrouvent coupés en deux par une frontière ; d'autres, qui ne s'entendaient pas, sont réunis dans la même colonie. La plupart de ces frontières sont devenues celles des États africains d'aujourd'hui.",
 qp=V('Les frontières de l’Afrique ont été tracées par les Africains eux-mêmes.', 0),
 qc=W('Pourquoi tant de frontières africaines sont-elles des lignes droites ? Quelle conséquence pour les peuples ?', 'Elles ont été tracées en Europe, sur des cartes, sans tenir compte du terrain ni des habitants. Des peuples sont coupés en deux ; d’autres, parfois rivaux, sont réunis dans la même colonie, puis dans le même État.')),
'colonies-4': dict(kind='fiche', t='Fiche : à combien de temps de la France ?', src='Fiche de l’atlas ; durées données en ordre de grandeur.',
 txt="Vers 1860, un voilier met environ quatre mois pour aller de France en Nouvelle-Calédonie, en contournant l'Afrique par le cap de Bonne-Espérance.\nAprès l'ouverture du canal de Suez (1869), avec les paquebots à vapeur, le voyage dure moins de deux mois dans les années 1880.\nLe courrier, les ordres du gouvernement et les renforts mettent donc des semaines à arriver. Sur place, le gouverneur décide presque seul.",
 qp=Q('Vers 1860, combien de temps dure le voyage de France en Nouvelle-Calédonie en voilier ?', ['Environ quatre mois', 'Une semaine', 'Deux ans']),
 qc=W('Quelle conséquence cette distance a-t-elle sur la façon de gouverner la colonie ?', 'Les ordres de Paris mettent des semaines ou des mois à arriver : le gouverneur, sur place, décide presque seul, et la métropole contrôle peu ce qui se passe dans la colonie.')),
'colonies-0': dict(kind='fiche', t='Fiche : le nickel calédonien, une matière première de l’empire', src='Fiche de l’atlas.',
 txt="En 1864, l’ingénieur Jules Garnier découvre en Nouvelle-Calédonie un minerai vert, riche en nickel. Les mines de Thio fournissent le minerai à partir de 1875 ; la Société Le Nickel est fondée en 1880.\nLe nickel rend l’acier plus dur et ne rouille pas : les usines d’Europe en veulent pour les machines, les pièces de monnaie, puis les blindages des navires de guerre.\nLe minerai part vers l’Europe par bateau. À la fin du XIXe siècle, la Nouvelle-Calédonie est l’un des tout premiers producteurs de nickel du monde.",
 qp=Q('À quoi sert le nickel calédonien en Europe ?', ['À fabriquer des aciers plus durs et des pièces de monnaie', 'À nourrir les ouvriers', 'À chauffer les maisons']),
 qc=W('Montre, avec l’exemple du nickel, le rôle qu’une colonie joue pour les usines de la métropole.', 'La colonie fournit une matière première, le minerai de nickel, qui part par bateau vers les usines d’Europe. Celles-ci en font des aciers, des pièces de monnaie, des blindages : le minerai est transformé et vendu ailleurs.')),
'colonies-3': dict(kind='fiche', t='Fiche : le télégraphe, les nerfs de l’empire', src='Fiche de l’atlas ; durées données en ordre de grandeur.',
 txt="Vers 1850, une lettre met plus d’un mois pour aller de Londres en Inde.\nEn 1870, un câble télégraphique posé au fond des mers relie Londres à Bombay : un message arrive en quelques heures. L’Australie est reliée en 1872. En 1902, un câble traverse tout le Pacifique.\nLa Nouvelle-Calédonie est reliée à l’Australie par un câble en 1893.\nGrâce au télégraphe, Londres peut donner des ordres à ses gouverneurs, déplacer ses navires et connaître les prix du coton ou du blé presque aussitôt.",
 qp=V('Avec le télégraphe, un message met encore plus d’un mois pour aller de Londres en Inde.', 0),
 qc=W('Explique pourquoi le télégraphe aide le Royaume-Uni à tenir son empire.', 'Les ordres et les nouvelles circulent en quelques heures au lieu de plusieurs semaines : Londres peut diriger ses gouverneurs, déplacer sa flotte et suivre le commerce presque en direct.')),
'colonies-5': dict(kind='fiche', t='Fiche : résister sans armes, le Congrès national indien', src='Fiche de l’atlas.',
 txt="En décembre 1885, soixante-douze délégués indiens se réunissent à Bombay : avocats, journalistes, professeurs. Ils fondent le Congrès national indien.\nIls ne prennent pas les armes. Ils écrivent, pétitionnent, tiennent des réunions. Ils demandent d’abord plus d’Indiens dans l’administration et dans les conseils qui préparent les lois.\nPeu à peu, le Congrès réclame que l’Inde se gouverne elle-même. C’est ce mouvement, dirigé plus tard par Gandhi, qui conduira le pays à l’indépendance en 1947.",
 qp=Q('Comment les fondateurs du Congrès national indien résistent-ils ?', ['Par des pétitions et des réunions', 'Par une guerre', 'En quittant le pays']),
 qc=W('Montre que l’on peut résister à la colonisation sans prendre les armes.', 'Le Congrès national indien, fondé en 1885, utilise la parole et l’écrit : réunions, pétitions, journaux. Il demande d’abord plus de place pour les Indiens, puis que l’Inde se gouverne elle-même.')),
'guerres-0': dict(kind='fiche', t='Fiche : les monuments aux morts', src='Fiche de l’atlas.',
 txt="Après 1918, presque toutes les communes de France font construire un monument aux morts. On y grave le nom des soldats de la commune tués à la guerre.\nEn Nouvelle-Calédonie aussi, les communes et les tribus ont leurs monuments et leurs plaques : on y lit les noms des soldats d’origine européenne et ceux des tirailleurs kanak.\nDepuis 1922, le 11 novembre est un jour férié : on se rassemble devant le monument pour se souvenir.",
 qp=Q('Que grave-t-on sur un monument aux morts ?', ['Le nom des soldats de la commune tués à la guerre', 'Le nom des généraux vainqueurs', 'La liste des batailles gagnées']),
 qc=W('À quoi servent les monuments aux morts et la cérémonie du 11 novembre ?', 'À garder le souvenir des soldats tués, dont les noms sont gravés, et à rappeler chaque année le prix de la guerre.')),
'guerres-1': dict(kind='fiche', t='Fiche : Verdun, 1916', src='Fiche de l’atlas ; chiffres arrondis.',
 txt="Le 21 février 1916, l’armée allemande attaque les forts qui protègent Verdun, en Lorraine. Elle veut user l’armée française.\nLa bataille dure dix mois. Des millions d’obus retournent le sol ; des villages entiers disparaissent. Les soldats se battent pour quelques mètres de terrain.\nEn décembre 1916, le front est presque revenu à son point de départ. Plus de 300 000 soldats français et allemands sont morts.",
 qp=Q('Combien de temps dure la bataille de Verdun ?', ['Dix mois', 'Deux jours', 'Quatre ans']),
 qc=W('Pourquoi Verdun est-elle devenue le symbole de la Grande Guerre ?', 'Dix mois de combats, des millions d’obus, plus de 300 000 morts pour un front qui ne bouge presque pas : la bataille résume la violence de la guerre de tranchées.')),
'guerres-2': dict(kind='fiche', t='Fiche : la propagande, convaincre et embrigader', src='Fiche de l’atlas.',
 txt="Dans un régime totalitaire, l’État contrôle tout ce que la population lit, voit et entend : journaux, radio, cinéma, affiches, livres d’école.\nLe portrait du chef est partout. De grands rassemblements montrent la force du régime.\nLes enfants et les adolescents entrent dans des organisations de jeunesse où on leur apprend à obéir et à admirer le chef : Jeunesses hitlériennes en Allemagne, Balilla en Italie, Pionniers en URSS.",
 qp=V('Dans un régime totalitaire, les journaux et la radio sont libres.', 0),
 qc=W('Explique à quoi servent la propagande et les organisations de jeunesse dans un régime totalitaire.', 'À faire accepter le régime et son chef par toute la population, et à former dès l’enfance des personnes obéissantes, qui ne connaissent pas d’autres idées.')),
'guerres-3': dict(kind='fiche', t='Fiche : le ghetto de Varsovie', src='Fiche de l’atlas ; chiffres arrondis.',
 txt="En 1940, les nazis obligent les Juifs de Varsovie, en Pologne, à vivre dans un quartier fermé par un mur : le ghetto. Environ 400 000 personnes s’y entassent ; la faim et les maladies tuent des dizaines de milliers d’entre elles.\nÀ l’été 1942, plus de 250 000 habitants du ghetto sont déportés en train vers le centre de mise à mort de Treblinka.\nEn avril 1943, les derniers habitants prennent les armes. Ils résistent près d’un mois à l’armée allemande, qui détruit le ghetto.",
 qp=Q('Qu’est-ce qu’un ghetto, pendant la Seconde Guerre mondiale ?', ['Un quartier fermé où les nazis enferment les Juifs', 'Un camp de soldats', 'Une usine d’armement']),
 qc=W('Montre que le ghetto de Varsovie est une étape de la Shoah.', 'Les Juifs y sont d’abord enfermés et affamés, puis déportés en 1942 vers le centre de mise à mort de Treblinka ; ceux qui restent sont tués lors de la destruction du ghetto en 1943.')),
'guerres-4': dict(kind='fiche', t='Fiche : la Plaine des Gaïacs, un aérodrome de guerre', src='Fiche de l’atlas.',
 txt="En 1942, l’armée américaine construit plusieurs aérodromes en Nouvelle-Calédonie. L’un des plus grands se trouve à la Plaine des Gaïacs, près de Pouembout.\nLes avions venus des États-Unis y font escale avant de repartir vers l’Australie ou vers les combats des îles Salomon.\nPour les habitants de la région, c’est un bouleversement : des milliers de soldats, des camions, des pistes, des hangars apparaissent en quelques mois. Après la guerre, les Américains repartent et la brousse reprend peu à peu sa place.",
 qp=Q('Près de quelle commune se trouve l’aérodrome de la Plaine des Gaïacs ?', ['Pouembout', 'Nouméa', 'Lifou']),
 qc=W('Montre, avec l’exemple de la Plaine des Gaïacs, que la guerre du Pacifique transforme la Nouvelle-Calédonie.', 'En quelques mois, l’armée américaine construit un grand aérodrome en pleine brousse : des milliers de soldats, des pistes, des camions. Le pays devient une base arrière de la guerre.')),
'guerres-5': dict(kind='fiche', t='Fiche : Bir Hakeim, mai-juin 1942', src='Fiche de l’atlas ; chiffres arrondis.',
 txt="Bir Hakeim est un ancien point d’eau dans le désert de Libye. En mai 1942, environ 3 700 soldats de la France libre, commandés par le général Kœnig, y sont encerclés par les armées allemande et italienne du général Rommel.\nIls tiennent deux semaines, du 26 mai au 11 juin, puis réussissent à sortir de nuit. Leur résistance donne à l’armée britannique le temps de se replier.\nLe Bataillon du Pacifique, formé de Tahitiens, de Calédoniens et de Néo-Hébridais, y combat ; son chef, le lieutenant-colonel Broche, y est tué.",
 qp=Q('Où se trouve Bir Hakeim ?', ['Dans le désert de Libye', 'En Normandie', 'Dans le Pacifique']),
 qc=W('Pourquoi Bir Hakeim est-elle une bataille importante pour la France libre ?', 'Pour la première fois depuis 1940, des soldats français tiennent tête à l’armée allemande : la France libre montre aux Alliés qu’elle compte dans la guerre. Des Calédoniens et des Tahitiens y combattent.')),
'monde45-0': dict(kind='fiche', t='Fiche : le plan Marshall', src='Fiche de l’atlas ; chiffres arrondis.',
 txt="En 1947, l’Europe est ruinée par la guerre : on manque de nourriture, de charbon, de logements.\nLes États-Unis proposent une aide à tous les pays d’Europe : le plan Marshall. Seize pays d’Europe de l’Ouest l’acceptent et reçoivent environ 13 milliards de dollars en quatre ans.\nL’URSS refuse cette aide et oblige les pays d’Europe de l’Est à la refuser aussi : pour elle, c’est un moyen pour les États-Unis d’étendre leur influence.",
 qp=Q('Qui refuse le plan Marshall ?', ['L’URSS et les pays d’Europe de l’Est', 'La France et le Royaume-Uni', 'Les États-Unis']),
 qc=W('Montre que le plan Marshall contribue à couper l’Europe en deux.', 'L’Europe de l’Ouest accepte l’aide américaine et se reconstruit avec elle ; l’URSS la refuse et l’interdit à l’Europe de l’Est : deux camps se forment.')),
'monde45-1': dict(kind='fiche', t='Fiche : l’affaire du Rainbow Warrior', src='Fiche de l’atlas.',
 txt="En juillet 1985, le Rainbow Warrior, un navire de l’association écologiste Greenpeace, fait escale à Auckland, en Nouvelle-Zélande. Il doit partir protester contre les essais nucléaires français à Moruroa.\nDans la nuit du 10 juillet, deux bombes posées par des agents des services secrets français coulent le navire. Un photographe de l’équipage est tué.\nL’affaire provoque un scandale mondial. Elle abîme pour longtemps l’image de la France dans le Pacifique.",
 qp=Q('Que voulait faire l’équipage du Rainbow Warrior ?', ['Protester contre les essais nucléaires français', 'Pêcher la baleine', 'Transporter du nickel']),
 qc=W('Pourquoi cette affaire a-t-elle abîmé l’image de la France dans le Pacifique ?', 'Des agents français ont coulé un navire dans le port d’un pays ami, tuant un homme, pour protéger des essais nucléaires que les pays de la région refusaient.')),
'monde45-2': dict(kind='fiche', t='Fiche : la marche du sel', src='Fiche de l’atlas ; chiffres arrondis.',
 txt="En Inde, les Britanniques interdisent aux habitants de récolter du sel : il faut l’acheter et payer une taxe.\nEn mars 1930, Gandhi quitte son village avec quelques dizaines de compagnons. Il marche vingt-quatre jours, près de 400 km, jusqu’à la mer. Des milliers d’Indiens le rejoignent en chemin.\nArrivé sur la plage, il ramasse une poignée de sel : il vient de désobéir à la loi. Partout dans le pays, des Indiens l’imitent. Environ 60 000 sont emprisonnés, dont Gandhi.",
 qp=Q('Que fait Gandhi en arrivant à la mer ?', ['Il ramasse du sel, ce que la loi interdit', 'Il attaque un fort britannique', 'Il prend un bateau pour Londres']),
 qc=W('Montre que la marche du sel est un acte de désobéissance non violente.', 'Gandhi viole volontairement une loi qu’il juge injuste, sans frapper ni menacer personne, et accepte d’aller en prison : il montre que les Britanniques ne peuvent pas gouverner un peuple qui refuse d’obéir.')),
'monde45-3': dict(kind='fiche', t='Fiche : le Forum des îles du Pacifique', src='Fiche de l’atlas.',
 txt="En 1971, les premiers États indépendants du Pacifique, avec l’Australie et la Nouvelle-Zélande, créent le Forum du Pacifique Sud. Ils veulent parler d’une seule voix face aux grandes puissances.\nDevenu le Forum des îles du Pacifique, il réunit aujourd’hui dix-huit membres. Son siège est à Suva, aux Fidji.\nLa Nouvelle-Calédonie et la Polynésie française en sont membres à part entière depuis 2016. On y discute du climat, de la pêche, de la sécurité.",
 qp=V('La Nouvelle-Calédonie est membre du Forum des îles du Pacifique.', 1),
 qc=W('À quoi sert le Forum des îles du Pacifique ?', 'À permettre à de petits États et territoires de parler d’une seule voix sur les sujets qui les concernent tous : le climat, la pêche, la sécurité.')),
'monde45-4': dict(kind='fiche', t='Fiche : le franc CFP', src='Fiche de l’atlas.',
 txt="Le franc CFP est créé en décembre 1945 pour les territoires français du Pacifique. On l’utilise aujourd’hui en Nouvelle-Calédonie, en Polynésie française et à Wallis-et-Futuna.\nSa valeur est fixée par rapport à l’euro : 1 000 francs CFP valent 8,38 euros, et ce taux ne change pas.\nLes billets et les pièces sont fabriqués pour ces trois territoires seulement : on ne peut pas payer avec en France métropolitaine.",
 qp=Q('Combien valent 1 000 francs CFP ?', ['8,38 euros', '1 000 euros', '1 euro']),
 qc=W('Explique pourquoi on dit que le franc CFP est « lié » à l’euro.', 'Sa valeur est fixe par rapport à l’euro : 1 000 francs CFP valent toujours 8,38 euros. Si l’euro monte ou baisse face aux autres monnaies, le franc CFP le suit.')),
'monde45-5': dict(kind='fiche', t='Fiche : Tuvalu face à la montée des eaux', src='Fiche de l’atlas ; chiffres arrondis.',
 txt="Tuvalu est un État du Pacifique formé de neuf petites îles, des atolls pour la plupart. Environ 11 000 personnes y vivent. Le point le plus haut ne dépasse la mer que de quelques mètres.\nAvec le réchauffement du climat, la mer monte. Les grandes marées inondent les routes et les jardins ; le sel gagne l’eau douce.\nEn 2023, Tuvalu a signé un accord avec l’Australie : chaque année, des habitants pourront s’y installer. Mais les Tuvaluans veulent d’abord sauver leur pays et leur culture.",
 qp=Q('Pourquoi Tuvalu est-il menacé ?', ['La mer monte et ses îles sont très basses', 'Un volcan s’y réveille', 'Il n’y pleut plus']),
 qc=W('Montre que la montée des eaux menace l’existence même de Tuvalu.', 'Ses îles ne dépassent la mer que de quelques mètres : inondations, eau douce salée, terres perdues. Le pays a même prévu avec l’Australie l’accueil d’une partie de ses habitants.')),
'republique-0': dict(kind='fiche', t='Fiche : la Sécurité sociale', src='Fiche de l’atlas.',
 txt="La Sécurité sociale est créée par deux ordonnances d’octobre 1945. Elle est mise en place par le ministre Ambroise Croizat et le haut fonctionnaire Pierre Laroque.\nLe principe est simple : chacun cotise selon ses moyens et reçoit selon ses besoins. Les salariés et les employeurs versent une partie des salaires dans une caisse commune.\nCette caisse rembourse les soins des malades, aide les familles, paie les retraites. Avant 1945, beaucoup de personnes ne pouvaient pas se soigner faute d’argent.",
 qp=Q('À quoi sert la Sécurité sociale ?', ['À rembourser les soins, aider les familles, payer les retraites', 'À payer les soldats', 'À construire des routes']),
 qc=W('Explique le principe « chacun cotise selon ses moyens et reçoit selon ses besoins ».', 'Tout le monde verse une part de son revenu dans une caisse commune ; celle-ci aide ceux qui en ont besoin (malades, familles, retraités), quels que soient leurs revenus : c’est la solidarité.')),
'republique-1': dict(kind='fiche', t='Fiche : le référendum', src='Fiche de l’atlas.',
 txt="Un référendum est un vote par lequel les citoyens répondent eux-mêmes par oui ou par non à une question.\nLe général de Gaulle s’en sert pour s’adresser directement aux Français, sans passer par les députés : pour faire approuver la Constitution (1958), l’indépendance de l’Algérie (1962), l’élection du président par tous les citoyens (1962).\nEn 1969, il pose une nouvelle question ; les Français répondent non ; il quitte le pouvoir. En Nouvelle-Calédonie, trois référendums ont porté sur l’indépendance, de 2018 à 2021.",
 qp=Q('Qui répond à la question posée lors d’un référendum ?', ['Tous les citoyens', 'Les députés seulement', 'Le président seul']),
 qc=W('Pourquoi dit-on que le référendum est un outil de démocratie directe ?', 'Les citoyens décident eux-mêmes, par oui ou par non, sans passer par leurs représentants : la Constitution de 1958 ou l’élection du président par tous ont été décidées ainsi.')),
'republique-2': dict(kind='fiche', t='Fiche : l’abolition de la peine de mort', src='Fiche de l’atlas.',
 txt="Jusqu’en 1981, un tribunal français pouvait condamner à mort ; le condamné était guillotiné.\nFrançois Mitterrand avait promis d’abolir cette peine. En septembre 1981, le ministre de la Justice, Robert Badinter, défend la loi devant les députés. Elle est votée par 363 voix contre 117, avec des voix de gauche et de droite.\nLa loi du 9 octobre 1981 abolit la peine de mort. Depuis 2007, la Constitution dit que « nul ne peut être condamné à la peine de mort ».",
 qp=Q('Quel ministre défend l’abolition de la peine de mort en 1981 ?', ['Robert Badinter', 'Simone Veil', 'Jacques Chirac']),
 qc=W('Montre que l’abolition n’est pas seulement la décision d’un camp politique.', 'La loi est votée par 363 voix contre 117 : des députés de gauche et de droite l’approuvent ; en 2007, l’interdiction est même inscrite dans la Constitution.')),
'republique-3': dict(kind='fiche', t='Fiche : les grands ensembles', src='Fiche de l’atlas.',
 txt="Après la guerre, la France manque de logements : des familles vivent dans des immeubles sans eau courante, voire dans des bidonvilles.\nDes années 1950 aux années 1970, l’État fait construire très vite de grands immeubles à la périphérie des villes : les grands ensembles. Leurs habitants y découvrent l’eau chaude, la salle de bains, le chauffage central.\nMais ces quartiers sont souvent loin des emplois et des commerces. Avec la crise des années 1970, le chômage y devient plus fort qu’ailleurs.",
 qp=V('Les premiers habitants des grands ensembles y trouvent plus de confort qu’avant.', 1),
 qc=W('Montre que les grands ensembles sont d’abord un progrès, puis une source de difficultés.', 'Ils offrent à des familles mal logées le confort moderne (eau chaude, salle de bains, chauffage). Mais, éloignés des emplois et des commerces, ils sont durement touchés par le chômage à partir des années 1970.')),
'republique-4': dict(kind='fiche', t='Fiche : le Mouvement de libération des femmes', src='Fiche de l’atlas.',
 txt="Le 26 août 1970, à Paris, quelques femmes veulent déposer une gerbe de fleurs sous l’Arc de triomphe « à la femme du soldat inconnu ». La police les arrête, mais les journaux en parlent : le Mouvement de libération des femmes (MLF) est né.\nSes militantes organisent des manifestations, des réunions, publient des journaux. En 1971, 343 femmes, dont des écrivaines et des actrices connues, signent un texte où elles déclarent avoir avorté, alors que la loi l’interdit.\nCes actions préparent les lois des années 1970.",
 qp=Q('Que veulent montrer les militantes le 26 août 1970 ?', ['Que l’on oublie les femmes', 'Qu’elles veulent devenir soldats', 'Qu’elles sont contre la République']),
 qc=W('Comment les mouvements féministes obtiennent-ils de nouvelles lois ?', 'Par des actions qui attirent l’attention (gerbe à « la femme du soldat inconnu », manifeste des 343), des manifestations et des publications : elles font évoluer l’opinion, puis les lois.')),
'republique-5': dict(kind='fiche', t='Fiche : la poignée de main du 26 juin 1988', src='Fiche de l’atlas.',
 txt="En mai 1988, après le drame d’Ouvéa, le Premier ministre Michel Rocard envoie en Nouvelle-Calédonie une mission chargée de renouer le dialogue.\nLe 26 juin 1988, à Paris, à l’hôtel Matignon, le chef indépendantiste Jean-Marie Tjibaou et le chef anti-indépendantiste Jacques Lafleur signent un accord et se serrent la main.\nCe geste devient le symbole de la paix retrouvée. Le 4 mai 1989, Jean-Marie Tjibaou est assassiné à Ouvéa par un indépendantiste opposé aux accords. Le centre culturel qui porte son nom ouvre à Nouméa en 1998.",
 qp=Q('Qui se serrent la main le 26 juin 1988 ?', ['Jean-Marie Tjibaou et Jacques Lafleur', 'Michel Rocard et François Mitterrand', 'De Gaulle et Pompidou']),
 qc=W('Pourquoi cette poignée de main est-elle devenue un symbole ?', 'Deux adversaires, à la tête de deux camps qui s’affrontaient violemment, choisissent de négocier et de faire la paix : leur geste montre que le dialogue est possible.')),
}
